import React, { useState, useEffect } from 'react';
import { Github, Linkedin, Mail, ExternalLink, Database, Cloud, Brain, Download, Menu, X, ArrowRight, Sparkles, Zap, Target, Binary } from 'lucide-react';

const Portfolio = () => {
  const [scrollY, setScrollY] = useState(0);
  const [activeSection, setActiveSection] = useState('hero');
  const [typedText, setTypedText] = useState('');
  const fullText = "AI & Machine Learning Engineer";

  // Typing effect for the headline
  useEffect(() => {
    if (typedText.length < fullText.length) {
      const timeout = setTimeout(() => {
        setTypedText(fullText.slice(0, typedText.length + 1));
      }, 100);
      return () => clearTimeout(timeout);
    }
  }, [typedText]);

  // Handle scroll for navigation
  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY);
      const sections = ['hero', 'experience', 'projects', 'skills'];
      const current = sections.find(section => {
        const element = document.getElementById(section);
        if (element) {
          const rect = element.getBoundingClientRect();
          return rect.top <= 150 && rect.bottom >= 150;
        }
        return false;
      });
      if (current) setActiveSection(current);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const projects = [
    {
      title: "Intelligent SQL-Gen",
      subtitle: "NLP to Queries via RAG",
      description: "Designed a RAG-based system that converts natural language queries into accurate SQL queries[cite: 25]. Implemented semantic schema linking using vector databases to identify relevant tables and columns[cite: 27].",
      tags: ["Python", "Azure OpenAI", "LangChain", "FAISS"],
      icon: "📊",
    },
    {
      title: "Deep Farming",
      subtitle: "Crop Disease Surveillance",
      description: "Developed a smart farming solution to detect crop diseases using deep learning and image processing[cite: 22]. Built a CNN model benchmarked against Random Forest[cite: 23].",
      tags: ["TensorFlow", "Flask", "NumPy", "Scikit-Learn"],
      icon: "🌱",
    },
    {
      title: "Healthcare Guidance Navigator",
      subtitle: "Agentic AI Support",
      description: "Developed a healthcare chatbot providing document-specific clinical guidance from PDFs and CSV files using Agentic AI[cite: 31].",
      tags: ["Agentic AI", "LangGraph", "ChromaDB", "Streamlit"],
      icon: "🏥",
    }
  ];

  return (
    <div className="bg-[#050505] text-white min-h-screen relative font-sans selection:bg-blue-500/30 overflow-x-hidden">
      
      {/* --- AI & DATA SCIENCE BACKGROUND --- */}
      <div className="fixed inset-0 z-0 pointer-events-none">
        {/* Abstract Data/AI Image Overlay */}
        <div 
          className="absolute inset-0 opacity-[0.07] grayscale contrast-125"
          style={{ 
            backgroundImage: `url('https://images.unsplash.com/photo-1620712943543-bcc4638d9980?auto=format&fit=crop&q=80&w=2000')`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
          }}
        ></div>
        
        {/* Animated Digital Neural Grid */}
        <div className="absolute inset-0 opacity-[0.15]" 
             style={{ backgroundImage: 'radial-gradient(#222 1px, transparent 1px)', backgroundSize: '30px 30px' }}>
        </div>

        {/* Ambient AI Glows */}
        <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-900/20 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/20 blur-[120px] rounded-full"></div>
      </div>

      {/* Navigation */}
      <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${scrollY > 50 ? 'backdrop-blur-xl bg-black/80 border-b border-white/5' : 'bg-transparent'}`}>
        <div className="max-w-7xl mx-auto px-6 py-5 flex justify-between items-center">
          <div className="text-xl font-black tracking-tighter flex items-center gap-2">
            <Binary className="text-blue-500 w-6 h-6" />
            ROHIT <span className="text-blue-500 uppercase italic">Harne</span>
          </div>
          <div className="hidden md:flex gap-8 items-center font-bold text-[10px] tracking-widest uppercase">
            {['Experience', 'Projects', 'Skills'].map((item) => (
              <a key={item} href={`#${item.toLowerCase()}`} className={`hover:text-blue-400 transition-colors ${activeSection === item.toLowerCase() ? 'text-blue-400' : 'text-gray-500'}`}>
                {item}
              </a>
            ))}
            <a href="mailto:rohitharne21@gmail.com" className="px-5 py-2 bg-blue-600 rounded-full hover:bg-blue-500 transition-all shadow-lg shadow-blue-500/20">
              Get In Touch
            </a>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section id="hero" className="relative min-h-screen flex items-center justify-center px-6 z-10 pt-20">
        <div className="max-w-7xl mx-auto w-full grid md:grid-cols-2 gap-16 items-center">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-[10px] font-bold tracking-widest text-blue-400 mb-8 uppercase">
              <Sparkles className="w-3 h-3" />
              Specializing in Generative AI
            </div>
            <h1 className="text-7xl md:text-9xl font-black mb-6 leading-[0.8] tracking-tighter">
              DATA <br /><span className="bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-400 bg-clip-text text-transparent">ENGINEER</span>
            </h1>
            <div className="h-10 mb-6">
              <p className="text-xl md:text-2xl font-light text-gray-400">
                {typedText}<span className="text-blue-500 animate-pulse">_</span>
              </p>
            </div>
            <p className="text-gray-400 text-lg max-w-lg mb-10 leading-relaxed">
              Hands-on experience building end-to-end AI solutions across healthcare and analytics domains[cite: 4]. Skilled in <span className="text-white">RAG systems</span> and production ML[cite: 5].
            </p>
            <div className="flex flex-wrap gap-4">
              <a href="#projects" className="px-8 py-4 bg-white text-black rounded-full font-bold hover:bg-blue-600 hover:text-white transition-all flex items-center gap-2">
                View Projects <ArrowRight className="w-4 h-4" />
              </a>
              {/* UPDATED RESUME LINK - MUST BE IN PUBLIC FOLDER */}
              <a href="/Rohit_Harne.Resume--.pdf" download className="px-8 py-4 border border-white/20 rounded-full font-bold hover:bg-white/10 transition-all flex items-center gap-2 text-sm uppercase tracking-widest">
                <Download className="w-4 h-4" /> Download CV
              </a>
            </div>
          </div>

          <div className="relative">
            <div className="relative group mx-auto max-w-sm">
              <div className="absolute -inset-4 bg-gradient-to-tr from-blue-600 to-purple-600 rounded-[2rem] blur-2xl opacity-20 group-hover:opacity-40 transition duration-1000"></div>
              
              {/* FIXED IMAGE PATH FOR PUBLIC FOLDER */}
              <img 
                src="/profile.jpg" 
                alt="Rohit Harne" 
                className="relative w-full aspect-[4/5] object-cover rounded-[2rem] border border-white/10 shadow-2xl grayscale hover:grayscale-0 transition-all duration-700"
                onError={(e) => e.target.src = "https://via.placeholder.com/400x500?text=Profile+Image"}
              />
              
              <div className="absolute -bottom-6 -right-6 p-6 bg-black/90 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl">
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-blue-500/20 rounded-xl">
                    <Brain className="w-6 h-6 text-blue-400" />
                  </div>
                  <div>
                    <p className="text-[10px] uppercase tracking-widest text-gray-500 font-bold">Industry Exp.</p>
                    <p className="text-xl font-bold italic">6 MONTHS</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Experience Section */}
      <section id="experience" className="py-32 px-6 z-10 relative">
        <div className="max-w-4xl mx-auto">
          <h2 className="text-3xl font-black mb-16 tracking-tight uppercase flex items-center gap-4">
            <Target className="text-blue-500" /> Professional Journey
          </h2>
          <div className="relative border-l-2 border-blue-500/20 pl-8 ml-4">
            <div className="absolute -left-[9px] top-0 w-4 h-4 bg-blue-600 rounded-full shadow-[0_0_15px_rgba(37,99,235,0.5)]"></div>
            <p className="text-blue-400 font-bold tracking-widest text-[10px] uppercase mb-1">AI & ML Intern</p>
            <h3 className="text-2xl font-bold text-white mb-4">Vcitysoft Pvt. Ltd. <span className="text-gray-500 font-normal text-lg ml-2">| 6 Months [cite: 10]</span></h3>
            <ul className="space-y-4 text-gray-400 text-sm leading-relaxed">
              <li className="flex gap-3"><span className="text-blue-500 mt-1.5">•</span> Developed analytical and AI solutions across financial and healthcare domains[cite: 11].</li>
              <li className="flex gap-3"><span className="text-blue-500 mt-1.5">•</span> Built scalable Python applications using OOP and Flask framework[cite: 12].</li>
              <li className="flex gap-3"><span className="text-blue-500 mt-1.5">•</span> Specialized in SQL databases and core ML libraries for intelligent systems[cite: 13].</li>
            </ul>
          </div>
        </div>
      </section>

      {/* Projects Grid */}
      <section id="projects" className="py-32 px-6 z-10 relative">
        <div className="max-w-7xl mx-auto">
          <div className="mb-20">
            <h2 className="text-4xl font-black mb-4 tracking-tighter uppercase italic">Technical Impact</h2>
            <div className="w-20 h-1 bg-blue-600"></div>
          </div>
          <div className="grid md:grid-cols-3 gap-8">
            {projects.map((project, idx) => (
              <div key={idx} className="group p-8 bg-white/[0.02] border border-white/5 rounded-[2.5rem] hover:bg-white/[0.05] transition-all hover:-translate-y-2">
                <div className="text-4xl mb-6">{project.icon}</div>
                <h3 className="text-xl font-bold mb-3 group-hover:text-blue-400 transition-colors uppercase">{project.title}</h3>
                <p className="text-gray-500 text-xs mb-8 leading-relaxed font-medium">{project.description}</p>
                <div className="flex flex-wrap gap-2 mb-10">
                  {project.tags.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-blue-500/5 rounded text-[8px] font-bold tracking-widest uppercase text-blue-300 border border-blue-500/10">{tag}</span>
                  ))}
                </div>
                <button className="flex items-center gap-2 text-[10px] font-black tracking-widest text-white/40 hover:text-white transition-colors uppercase">
                  Source Code <Github className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="py-20 border-t border-white/5 relative z-10">
        <div className="max-w-7xl mx-auto px-6 text-center">
          <p className="text-gray-500 text-[10px] tracking-widest uppercase font-bold mb-8 italic">Based in Pune, MH • 2025 Edition</p>
          <div className="flex justify-center gap-6">
            <a href="https://linkedin.com" className="p-4 bg-white/5 rounded-2xl hover:bg-blue-600 transition-all border border-white/5"><Linkedin className="w-5 h-5" /></a>
            <a href="https://github.com" className="p-4 bg-white/5 rounded-2xl hover:bg-blue-600 transition-all border border-white/5"><Github className="w-5 h-5" /></a>
            <a href="mailto:rohitharne21@gmail.com" className="p-4 bg-white/5 rounded-2xl hover:bg-blue-600 transition-all border border-white/5"><Mail className="w-5 h-5" /></a>
          </div>
        </div>
      </footer>

    </div>
  );
};

export default Portfolio;
